<?php
require_once __DIR__ . '/../helpers/auth.php'; requireLogin(); require_once __DIR__ . '/../../config/database.php';
$db=(new Database())->getConnection();
$ventas=$db->query("SELECT DATE(v.FechaVenta) Dia, COUNT(*) CantidadVentas, COALESCE(SUM(v.Total),0) TotalVentas FROM Ventas v WHERE YEAR(v.FechaVenta)=YEAR(CURDATE()) AND MONTH(v.FechaVenta)=MONTH(CURDATE()) GROUP BY DATE(v.FechaVenta) ORDER BY Dia DESC")->fetchAll();
$stock=$db->query("SELECT Codigo, Nombre, StockActual, StockMinimo FROM Productos WHERE Estado=1 AND StockActual<=StockMinimo ORDER BY StockActual, Nombre")->fetchAll();
$top=$db->query("SELECT p.Nombre, SUM(dv.Cantidad) Cantidad FROM DetalleVentas dv INNER JOIN Ventas v ON v.IdVenta=dv.IdVenta INNER JOIN Productos p ON p.IdProducto=dv.IdProducto WHERE MONTH(v.FechaVenta)=MONTH(CURDATE()) AND YEAR(v.FechaVenta)=YEAR(CURDATE()) GROUP BY p.IdProducto,p.Nombre ORDER BY Cantidad DESC LIMIT 10")->fetchAll();
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reportes - Mi Stock</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container-fluid p-4"><div class="d-flex justify-content-between mb-4"><h2>📊 Reportes</h2><a href="dashboard.php" class="btn btn-outline-secondary">Volver</a></div><div class="row g-4"><div class="col-lg-7"><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-bold">Ventas del mes</div><div class="table-responsive"><table class="table mb-0"><thead class="table-dark"><tr><th>Día</th><th>N° ventas</th><th>Total</th></tr></thead><tbody><?php foreach($ventas as $v):?><tr><td><?=date('d/m/Y',strtotime($v['Dia']))?></td><td><?=$v['CantidadVentas']?></td><td>$<?=number_format((float)$v['TotalVentas'],0,',','.')?></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-lg-5"><div class="card border-0 shadow-sm mb-4"><div class="card-header bg-white fw-bold">Stock bajo</div><div class="list-group list-group-flush"><?php foreach($stock as $s):?><div class="list-group-item d-flex justify-content-between"><span><?=e($s['Nombre'])?></span><span class="badge bg-danger"><?=$s['StockActual']?> / <?=$s['StockMinimo']?></span></div><?php endforeach;?></div></div><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-bold">Más vendidos del mes</div><div class="list-group list-group-flush"><?php foreach($top as $t):?><div class="list-group-item d-flex justify-content-between"><span><?=e($t['Nombre'])?></span><strong><?=$t['Cantidad']?></strong></div><?php endforeach;?></div></div></div></div></div></body></html>
